sys_ux_client_script.required_translations:
[
    {
        "message": "Attachment processing failed. Try again or contact your administrator."
    },
    {
        "message": "Can't display this information"
    }
]

sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({
    api,
    event,
    helpers,
    imports
}) {
    var attachmentErrorMessage = await helpers.translate("Attachment processing failed. Try again or contact your administrator.");
    api.setState("hideStandardTicket", true);
    api.setState("hideLoader", true);
    const webComponentsUtil = imports["sn_core_components.ComponentsUtil"]();

    if (!api.context.props.hideErrors) {
        var headerMessage = await helpers.translate("Can't display this information");
        api.setState("hideErrorComponent", false);
        api.setState("errorMessageHeader", {
            label: headerMessage
        });
        api.setState("errorMessageDescription", attachmentErrorMessage);
    } else
        console.error(attachmentErrorMessage);

    api.emit('SN_EMBEDX_CASE_VIEW#COMPONENT_ERROR', {
        errorType: "attachment_error",
        errorMessage: [{
            message: attachmentErrorMessage
        }]
    });
    api.emit('MACROPONENT_TRACK_USAGE_REQUESTED', { 
        event: '[WE] Case View - Component Error',
        value: {} 
    }); 
}
